3	const mineflayer = require('mineflayer')
4	const { pathfinder, Movements } = require('mineflayer-pathfinder')
5	const { makeBrain } = require('./brain')
6	const { findTarget, buildState, stateKey } = require('./perception')
7	const { makeScout, findNearest } = require('./behaviours/scout')
8	
9	const BEHAVIOURS = {
10	  fight: require('./behaviours/fight'),
11	  follow: require('./behaviours/follow'),
12	  roam: require('./behaviours/roam'),
13	}
14	
15	// Poll cadence when nobody is online: no JEV calls happen there, so waking
16	// up every 10 s just to re-scan the player list is plenty.
17	const IDLE_TICK_MS = 10000
18	const IDLE_LOG_MS = 60000
19	
20	function createTicker({ bot, brain, tickMs = 1000, idleTickMs = IDLE_TICK_MS, followName = '' }) {
21	  const ctx = { lastGoalKey: '', movements: null, paused: false }
22	  let inFlight = false
23	  let lastTargetPos = null
24	  let lastVisible = true
25	  let lastIdleLog = 0
26	  let lastStateKey = null
27	  let lastDecision = null
28	
29	  // mineflayer-pathfinder's stop() only sets a stopPathing flag that the
30	  // next setGoal consumes with the new goal — on an empty path with no goal
31	  // it latches and swallows the next goal, so skip it there. A live but
32	  // stationary goal (dynamic follow resting in range) still needs cancelling;
33	  // setGoal(null) clears it without latching. lastGoalKey still flips to
34	  // 'idle' for stop-once.
35	  function stopOnce() {
36	    if (ctx.lastGoalKey !== 'idle') {
37	      if (bot.pathfinder.isMoving()) bot.pathfinder.stop()
38	      else if (bot.pathfinder.goal) bot.pathfinder.setGoal(null)
39	      ctx.lastGoalKey = 'idle'
40	    }
41	  }
42	
43	  function applyDecision(decision, target, state) {
44	    const handler = BEHAVIOURS[decision.action]
45	    if (typeof handler === 'function') {
46	      handler(bot, ctx, target, state)
47	    } else {
48	      stopOnce()
49	    }
50	    if (ctx.movements) ctx.movements.allowSprinting = !!decision.sprint
51	    const dist = typeof state.distance_to_player === 'number' ? state.distance_to_player.toFixed(1) : 'none'
52	    console.log(`decision source=${decision.source} action=${decision.action} sprint=${decision.sprint} dist=${dist}`)
53	  }
54	
55	  function scheduleNext(fast) {
56	    const t = setTimeout(() => { void tick() }, fast ? tickMs : idleTickMs)
57	    if (t && typeof t.unref === 'function') t.unref()
58	  }
59	
60	  async function tick() {
61	    if (inFlight) { scheduleNext(lastVisible); return { decision: null, calledBrain: false } }
62	    inFlight = true
63	    let calledBrain = false
64	    try {
65	      if (ctx.paused) {
66	        // 'stop' parks the bot: perception + scout keep running while a
67	        // player is visible, but the brain is skipped and idle is dispatched
68	        // (stop once) — same cost guard as 'no player online', including no
69	        // scans with nobody online.
70	        const target = findTarget(bot, followName)
71	        lastVisible = !!target
72	        if (target) {
73	          const state = buildState(bot, target, lastTargetPos)
74	          lastTargetPos = state._lastTargetPos
75	          if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
76	          if (ctx.scout) ctx.scout.tick()
77	        } else {
78	          lastTargetPos = null
79	          lastDecision = null
80	          lastStateKey = null
81	        }
82	        stopOnce()
83	        const now = Date.now()
84	        if (now - lastIdleLog >= IDLE_LOG_MS) {
85	          lastIdleLog = now
86	          console.log('decision source=local-idle action=idle sprint=false dist=none')
87	        }
88	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
89	      }
90	      const target = findTarget(bot, followName)
91	      lastVisible = !!target
92	      if (!target) {
93	        // Cost fix: nobody online => no brain call at all, decide idle
94	        // locally, stop once, and stay quiet (at most one line per minute).
95	        stopOnce()
96	        lastTargetPos = null
97	        lastDecision = null
98	        lastStateKey = null
99	        const now = Date.now()
100	        if (now - lastIdleLog >= IDLE_LOG_MS) {
101	          lastIdleLog = now
102	          console.log('decision source=local-idle action=idle sprint=false dist=none')
103	        }
104	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
105	      }
106	      const state = buildState(bot, target, lastTargetPos)
107	      lastTargetPos = state._lastTargetPos
108	      // every-tick hooks (no body cost) go here
109	      if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
110	      if (ctx.scout) ctx.scout.tick()
111	      const key = stateKey(state)
112	      let decision
113	      if (lastDecision && key === lastStateKey) {
114	        decision = lastDecision
115	      } else {
116	        decision = await brain.decide(state)
117	        calledBrain = true
118	        // A stub-fallback means JEV failed; don't cache it or JEV would
119	        // never be retried while the player stands still.
120	        if (decision.source !== 'stub-fallback') {
121	          lastStateKey = key
122	          lastDecision = decision
123	        }
124	      }
125	      if (ctx.paused) {
126	        // 'stop' landed during the brain await: discard the stale decision
127	        // so one in-flight tick cannot issue a follow goal after the park.
128	        stopOnce()
129	        const now = Date.now()
130	        if (now - lastIdleLog >= IDLE_LOG_MS) {
131	          lastIdleLog = now
132	          console.log('decision source=local-idle action=idle sprint=false dist=none')
133	        }
134	        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain }
135	      }
136	      applyDecision(decision, target, state)
137	      return { decision, calledBrain }
138	    } catch (err) {
139	      console.error(`tick error: ${err && err.message ? err.message : err}`)
140	      return { decision: null, calledBrain }
141	    } finally {
142	      inFlight = false
143	      scheduleNext(lastVisible)
144	    }
145	  }
146	
147	  return {
148	    tick,
149	    start: () => scheduleNext(true),
150	    setMovements: (m) => { ctx.movements = m; bot.pathfinder.setMovements(m) },
151	    setFollow: (name) => { followName = name; ctx.lastGoalKey = ''; if (name) ctx.paused = false },
152	    stop: () => {
153	      ctx.paused = true
154	      stopOnce()
155	    }
156	  }
157	}
158	
159	function main() {
160	  const rawTick = parseInt(process.env.BRAIN_TICK_MS || '1000', 10)
161	  const tickMs = Number.isFinite(rawTick) ? rawTick : 1000
162	  const brain = makeBrain(process.env)
163	  const bot = mineflayer.createBot({
164	    host: process.env.MC_HOST || 'mc',
165	    port: parseInt(process.env.MC_PORT || '25565', 10),
166	    username: process.env.BOT_USERNAME || 'IdkBot',
167	    auth: 'offline' // offline-mode server; see README for the online-mode note
168	  })
169	  bot.loadPlugin(pathfinder)
170	  const ticker = createTicker({ bot, brain, tickMs, followName: process.env.BOT_FOLLOW || '' })
171	
172	  bot.once('spawn', () => {
173	    ticker.setMovements(new Movements(bot))
174	    console.log(`spawned as ${bot.username}`)
175	    ticker.start()
176	  })
