'use strict'

const mineflayer = require('mineflayer')
const { pathfinder, Movements } = require('mineflayer-pathfinder')
const { makeBrain } = require('./brain')
const { findTarget, buildState, stateKey } = require('./perception')
const { makeScout, findNearest } = require('./behaviours/scout')

const BEHAVIOURS = {
  fight: require('./behaviours/fight'),
  follow: require('./behaviours/follow'),
  roam: require('./behaviours/roam'),
}

// Poll cadence when nobody is online: no JEV calls happen there, so waking
// up every 10 s just to re-scan the player list is plenty.
const IDLE_TICK_MS = 10000
const IDLE_LOG_MS = 60000

function createTicker({ bot, brain, tickMs = 1000, idleTickMs = IDLE_TICK_MS, followName = '' }) {
  const ctx = { lastGoalKey: '', movements: null, paused: false }
  let inFlight = false
  let lastTargetPos = null
  let lastVisible = true
  let lastIdleLog = 0
  let lastStateKey = null
  let lastDecision = null

  // mineflayer-pathfinder's stop() only sets a stopPathing flag that the
  // next setGoal consumes with the new goal — on an empty path with no goal
  // it latches and swallows the next goal, so skip it there. A live but
  // stationary goal (dynamic follow resting in range) still needs cancelling;
  // setGoal(null) clears it without latching. lastGoalKey still flips to
  // 'idle' for stop-once.
  function stopOnce() {
    if (ctx.lastGoalKey !== 'idle') {
      if (bot.pathfinder.isMoving()) bot.pathfinder.stop()
      else if (bot.pathfinder.goal) bot.pathfinder.setGoal(null)
      ctx.lastGoalKey = 'idle'
    }
  }

  function applyDecision(decision, target, state) {
    const handler = BEHAVIOURS[decision.action]
    if (typeof handler === 'function') {
      handler(bot, ctx, target, state)
    } else {
      stopOnce()
    }
    if (ctx.movements) ctx.movements.allowSprinting = !!decision.sprint
    const dist = typeof state.distance_to_player === 'number' ? state.distance_to_player.toFixed(1) : 'none'
    console.log(`decision source=${decision.source} action=${decision.action} sprint=${decision.sprint} dist=${dist}`)
  }

  function scheduleNext(fast) {
    const t = setTimeout(() => { void tick() }, fast ? tickMs : idleTickMs)
    if (t && typeof t.unref === 'function') t.unref()
  }

  async function tick() {
    if (inFlight) { scheduleNext(lastVisible); return { decision: null, calledBrain: false } }
    inFlight = true
    let calledBrain = false
    try {
      if (ctx.paused) {
        // 'stop' parks the bot: perception + scout keep running while a
        // player is visible, but the brain is skipped and idle is dispatched
        // (stop once) — same cost guard as 'no player online', including no
        // scans with nobody online.
        const target = findTarget(bot, followName)
        lastVisible = !!target
        if (target) {
          const state = buildState(bot, target, lastTargetPos)
          lastTargetPos = state._lastTargetPos
          if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
          if (ctx.scout) ctx.scout.tick()
        } else {
          lastTargetPos = null
          lastDecision = null
          lastStateKey = null
        }
        stopOnce()
        const now = Date.now()
        if (now - lastIdleLog >= IDLE_LOG_MS) {
          lastIdleLog = now
          console.log('decision source=local-idle action=idle sprint=false dist=none')
        }
        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
      }
      const target = findTarget(bot, followName)
      lastVisible = !!target
      if (!target) {
        // Cost fix: nobody online => no brain call at all, decide idle
        // locally, stop once, and stay quiet (at most one line per minute).
        stopOnce()
        lastTargetPos = null
        lastDecision = null
        lastStateKey = null
        const now = Date.now()
        if (now - lastIdleLog >= IDLE_LOG_MS) {
          lastIdleLog = now
          console.log('decision source=local-idle action=idle sprint=false dist=none')
        }
        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
      }
      const state = buildState(bot, target, lastTargetPos)
      lastTargetPos = state._lastTargetPos
      // every-tick hooks (no body cost) go here
      if (!ctx.scout && bot.registry) ctx.scout = makeScout(bot)
      if (ctx.scout) ctx.scout.tick()
      const key = stateKey(state)
      let decision
      if (lastDecision && key === lastStateKey) {
        decision = lastDecision
      } else {
        decision = await brain.decide(state)
        calledBrain = true
        // A stub-fallback means JEV failed; don't cache it or JEV would
        // never be retried while the player stands still.
        if (decision.source !== 'stub-fallback') {
          lastStateKey = key
          lastDecision = decision
        }
      }
      if (ctx.paused) {
        // 'stop' landed during the brain await: discard the stale decision
        // so one in-flight tick cannot issue a follow goal after the park.
        stopOnce()
        const now = Date.now()
        if (now - lastIdleLog >= IDLE_LOG_MS) {
          lastIdleLog = now
          console.log('decision source=local-idle action=idle sprint=false dist=none')
        }
        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain }
      }
      applyDecision(decision, target, state)
      return { decision, calledBrain }
    } catch (err) {
      console.error(`tick error: ${err && err.message ? err.message : err}`)
      return { decision: null, calledBrain }
    } finally {
      inFlight = false
      scheduleNext(lastVisible)
    }
  }

  return {
    tick,
    start: () => scheduleNext(true),
    setMovements: (m) => { ctx.movements = m; bot.pathfinder.setMovements(m) },
    setFollow: (name) => { followName = name; ctx.lastGoalKey = ''; if (name) ctx.paused = false },
    stop: () => {
      ctx.paused = true
      stopOnce()
    }
  }
}

function main() {
  const rawTick = parseInt(process.env.BRAIN_TICK_MS || '1000', 10)
  const tickMs = Number.isFinite(rawTick) ? rawTick : 1000
  const brain = makeBrain(process.env)
  const bot = mineflayer.createBot({
    host: process.env.MC_HOST || 'mc',
    port: parseInt(process.env.MC_PORT || '25565', 10),
    username: process.env.BOT_USERNAME || 'IdkBot',
    auth: 'offline' // offline-mode server; see README for the online-mode note
  })
  bot.loadPlugin(pathfinder)
  const ticker = createTicker({ bot, brain, tickMs, followName: process.env.BOT_FOLLOW || '' })

  bot.once('spawn', () => {
    ticker.setMovements(new Movements(bot))
    console.log(`spawned as ${bot.username}`)
    ticker.start()
  })

  bot.on('chat', (username, message) => handleChat(bot, ticker, username, message))

  function fatal(where, err) {
    console.error(`${where}: ${err && err.message ? err.message : err}`)
    process.exit(1)
  }
  bot.on('end', (reason) => fatal('end', reason || 'disconnected'))
  bot.on('error', (err) => fatal('error', err))
  bot.on('kicked', (reason) => fatal('kicked', reason))
}

function handleChat(bot, ticker, username, message) {
  if (username === bot.username) return
  const msg = message.toLowerCase().trim()
  if (msg === 'follow me') {
    if (ticker) ticker.setFollow(username)
    bot.chat(`Following ${username}`)
  } else if (msg === 'stop') {
    if (ticker) {
      ticker.setFollow('')
      ticker.stop()
    }
  } else {
    const m = msg.match(/^find me\s+(\S+)$/)
    if (m) {
      const name = m[1]
      const res = findNearest(bot, name)
      if (res === 'unknown') {
        bot.chat(`unknown block: ${name}`)
      } else if (!res) {
        bot.chat(`no ${name} within 48 blocks`)
      } else {
        bot.chat(`${res.name} at ${res.position.x} ${res.position.y} ${res.position.z} (${res.distance} blocks)`)
      }
    }
  }
}

if (require.main === module) main()

module.exports = { createTicker, BEHAVIOURS, handleChat }

'use strict'

const { goals } = require('mineflayer-pathfinder')

// ponytail: one function, no base class or activate/deactivate hooks —
// fight/scout will each add one sibling module plus a one-line registration.
function follow(bot, ctx, target, state) {
  if (!target) return
  const key = `follow:${target.username || target.id}`
  // Re-issue while standing still: the first path can fail on an empty
  // (not yet loaded) world, and a dynamic goal only re-paths when the
  // target moves — so retry until the bot is actually moving.
  if (key !== ctx.lastGoalKey || !bot.pathfinder.isMoving()) {
    bot.pathfinder.setGoal(new goals.GoalFollow(target, 3), true)
    ctx.lastGoalKey = key
  }
}

module.exports = follow

'use strict'

const HOSTILE_NAMES = new Set([
  'zombie', 'skeleton', 'spider', 'creeper', 'enderman', 'witch',
  'slime', 'husk', 'stray', 'drowned', 'pillager', 'phantom', 'blaze',
  'ghast', 'piglin_brute', 'hoglin', 'zoglin', 'cave_spider', 'silverfish',
  'endermite', 'vex', 'vindicator', 'evoker', 'ravager', 'warden', 'breeze',
  'bogged', 'creaking'
])

// Fight-candidate ranges: same numbers the brain criteria state (3nt.2) —
// a hostile counts for fight when within 8 blocks of the bot OR 6 of the player.
const FIGHT_RANGE_BOT = 8
const FIGHT_RANGE_PLAYER = 6

// ponytail: creepers are excluded from fight targets, not fled from —
// hitting one near the player makes it explode next to the player, and
// fleeing is out of scope.
function isFightTarget(entity, botPos, playerPos) {
  if (!entity || entity.type === 'player' || !entity.position) return false
  const name = entity.name || entity.mobType || ''
  if (!HOSTILE_NAMES.has(name) || name === 'creeper') return false
  if (entity.position.distanceTo(botPos) <= FIGHT_RANGE_BOT) return true
  return !!playerPos && entity.position.distanceTo(playerPos) <= FIGHT_RANGE_PLAYER
}

// Dedup key: distance rounded to 1 block + same flags => reuse last decision,
// skip the JEV call. Staleness is at most half a block of travel.
function stateKey(state) {
  const d = state.distance_to_player
  const hd = state.hostile_distance
  return [
    typeof d === 'number' ? Math.round(d) : 'none',
    !!state.player_visible, !!state.player_moving,
    state.bot_health, state.bot_food, state.nearby_hostiles,
    typeof hd === 'number' ? Math.round(hd) : 'none',
    !!state.hostile_near_player
  ].join('|')
}

function findTarget(bot, followName) {
  if (followName) return (bot.players[followName] && bot.players[followName].entity) || null
  let best = null
  let bestDist = Infinity
  for (const player of Object.values(bot.players)) {
    if (!player.entity) continue
    if (player.username === bot.username) continue
    const d = bot.entity.position.distanceTo(player.entity.position)
    if (d < bestDist) {
      bestDist = d
      best = player.entity
    }
  }
  return best
}

function buildState(bot, target, lastTargetPos) {
  let distanceToPlayer = null
  let playerMoving = false
  let nextPos = null
  if (target) {
    distanceToPlayer = bot.entity.position.distanceTo(target.position)
    if (lastTargetPos) {
      playerMoving = target.position.distanceTo(lastTargetPos) > 0.1
    }
    nextPos = target.position.clone()
  }
  let nearbyHostiles = 0
  for (const entity of Object.values(bot.entities)) {
    if (entity.type === 'player' || !entity.position) continue
    const name = entity.name || entity.mobType || ''
    if (!HOSTILE_NAMES.has(name)) continue
    if (entity.position.distanceTo(bot.entity.position) < 16) nearbyHostiles++
  }
  let hostile = null
  let hostileDistance = null
  let hostilePlayerDistance = Infinity
  for (const entity of Object.values(bot.entities)) {
    if (!isFightTarget(entity, bot.entity.position, target && target.position)) continue
    const dBot = entity.position.distanceTo(bot.entity.position)
    const dPlayer = target ? entity.position.distanceTo(target.position) : Infinity
    if (hostileDistance === null || dBot < hostileDistance) {
      hostile = entity
      hostileDistance = dBot
      hostilePlayerDistance = dPlayer
    }
  }
  const state = {
    distance_to_player: distanceToPlayer,
    player_visible: !!target,
    player_moving: playerMoving,
    bot_health: typeof bot.health === 'number' ? bot.health : 20,
    bot_food: typeof bot.food === 'number' ? bot.food : 20,
    nearby_hostiles: nearbyHostiles,
    hostile_distance: hostileDistance,
    hostile_near_player: hostile ? hostilePlayerDistance <= FIGHT_RANGE_PLAYER : false,
    hostile
  }
  state._lastTargetPos = nextPos
  return state
}

module.exports = { findTarget, buildState, stateKey, HOSTILE_NAMES, isFightTarget }

